scwin.onpageload = function() {

};

scwin.fn_ViewManualKeyWord = function(submitManualClssId) {
	// 매뉴얼 검색 결과 팝업 열기
	if ($c.util.isEmpty(submitManualClssId)) {
		$c.win.alert("검색어를 입력해주세요.");
		return;
	}

	var url = $c.sbm.getContextPath() + "/support/manual.do?method=searchSubmitManual&submitManualClssId=" + encodeURIComponent(submitManualClssId);
	var opts = {
		"scrollbars": "yes",
		"toolbar": "no",
		"resizable": "no",
		"width": 1000,
		"height": 650,
		"left": 10,
		"top": 10,
		"name": "manualWin"
	};
	$c.win.openPopup(url, opts);
};

/* 연부과금조회 */
scwin.btn_cm1_onclick = function (e) {
    var url = $c.sbm.getContextPath() + "/issue/yearAssessmentFee.do?method=searchYearAssessmentFee";
	$c.win.moveUrl(url);

    // ULDFIL30100
    var param = {
        "dataObject": {
            "type": "json",
            "name": "paramData",
            // "data": paramObj
        }
    };
    $c.win.moveUrl("/lst/issue/ULDFIL30100.xml", param);
};

